update public.hard_sector_sections as section set body=(
 select jsonb_object_agg(entry.key,jsonb_set(
 entry.value || coalesce(section.body->entry.key,'{}'::jsonb),
 '{stats}',(select jsonb_agg(stat.value || coalesce(section.body#>array[entry.key,'stats',(stat.ordinality-1)::text],'{}'::jsonb) order by stat.ordinality)
 from jsonb_array_elements(entry.value->'stats') with ordinality as stat(value,ordinality))
